<?php
namespace App\Core\Connectors\Drivers;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Models\ConnectorConnection;
final class GoogleSearchConsoleConnector extends AbstractConnector {public function id():string{return 'google_search_console';}public function label():string{return 'Google Search Console';}public function actions():array{return [new ConnectorAction('search_analytics','Query Search Console performance data with date ranges, dimensions and filters.',RiskLevel::Read,['type'=>'object','properties'=>['site_url'=>['type'=>'string'],'startDate'=>['type'=>'string'],'endDate'=>['type'=>'string'],'dimensions'=>['type'=>'array','items'=>['type'=>'string']],'rowLimit'=>['type'=>'integer']],'required'=>['site_url','startDate','endDate']])];}public function configurationSchema():array{return ['credentials'=>['access_token'=>['type'=>'password','required'=>true]],'fields'=>[]];}private function req(ConnectorConnection $c){return $this->client(['Authorization'=>'Bearer '.$this->bearer($c,'access_token')]);}public function test(ConnectorConnection $c):bool{try{return $this->req($c)->get('https://www.googleapis.com/webmasters/v3/sites')->successful();}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);$site=(string)$a['site_url'];unset($a['site_url']);return ConnectorResult::success($this->req($c)->post('https://www.googleapis.com/webmasters/v3/sites/'.rawurlencode($site).'/searchAnalytics/query',$a)->throw()->json());}}
